import {listImports,attachImports} from './custom-data.js';
import {renderGroupedCatalog,allVariants,hydrateSelections} from './catalog-ui.js';
import { attachOrientation } from './orientation.js';
import { escapeHTML as esc } from './core.js';
import { pointInGeometry, layerMatches } from './atlas-core.js';
import { regionalEngine as maplibregl } from './atlas-leaflet.js';
const $=id=>document.getElementById(id),fmt=n=>Number(n||0).toLocaleString('fr-FR'),ROOT='data/atlas/';
const state={catalog:null,map:null,active:new Set(),loading:new Map(),sources:new Map(),analysis:false,zones:null,selectedZone:null,popup:null};
let toastTimer;function toast(s){$('toast').textContent=s;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,6000)}
async function json(path,signal){const r=await fetch(path,{signal});if(!r.ok)throw Error('Fichier indisponible : '+path+' ('+r.status+')');if(path.endsWith('.gz')&&!r.headers.get('Content-Encoding')?.includes('gzip'))return new Response(r.body.pipeThrough(new DecompressionStream('gzip'))).json();return r.json()}
function color(l){return state.catalog.categories.find(c=>l.category_ids.includes(c.id))?.color||'#456b56'}
function displayChunks(l){if(l.map_count>50000&&state.map.getZoom()<13&&l.overview_file)return [l.overview_file];const b=state.map.getBounds();return l.chunks.filter(c=>{const q=l.chunk_bounds?.[c];return !q||q[0]<=b[2]&&q[2]>=b[0]&&q[1]<=b[3]&&q[3]>=b[1]})}
const statusName=s=>({COMPLETE:'Collecte complète',PARTIAL:'Collecte partielle',ERROR:'Échec de collecte',FILE_VERIFIED:'Fichier vérifié'}[s]||s);
const stateName=s=>({READY:'Cartographiable',NO_NORMANDY_GEOMETRY:'Aucune géométrie normande extraite',MISSING_LOCAL_FILE:'Fichier local absent',RASTER_REFERENCE:'Raster à préparer',NON_SPATIAL_OR_ARCHIVE:'Table ou archive sans couche vectorielle',READ_ERROR:'Lecture à vérifier',GEOMETRY_REVIEW:'Géométrie ou projection à vérifier'}[s]||s);
function closeDetail(){$('detail').hidden=true}
function detail(html){$('detail').innerHTML='<button class="close" id="close-detail" aria-label="Fermer">×</button>'+html;$('detail').hidden=false;$('close-detail').onclick=closeDetail}
function saveView(){const u=new URL(location.href);u.searchParams.set('layers',[...state.active].join(','));if(state.map){const c=state.map.getCenter();u.searchParams.set('view',[c.lng.toFixed(4),c.lat.toFixed(4),state.map.getZoom().toFixed(2)].join(','))}history.replaceState(null,'',u)}
function renderLayers(){if(state.tree)renderGroupedCatalog(state,toggle,sourceDetail,saveView)}
function sourceDetail(l){detail(`<div class="eyebrow">${esc(l.origin)}</div><h2>${esc(l.display_name||l.name)}</h2><span class="badge ${l.status==='PARTIAL'?'partial':''}">${esc(statusName(l.status))}</span><p>${esc(l.categories.join(' · '))}</p><dl><dt>Objets retenus en Normandie</dt><dd>${fmt(l.map_count)}</dd><dt>État cartographique</dt><dd>${esc(stateName(l.map_state))}</dd><dt>Nom dans la source</dt><dd>${esc(l.name)}</dd><dt>Références du catalogue</dt><dd>${esc(l.entry_ids.join(', '))}</dd><dt>Usage documenté</dt><dd>${esc((l.use_cases||[]).join(' · '))}</dd><dt>Date du contrôle ou de collecte</dt><dd>${esc(l.collected_at||'Non renseignée')}</dd><dt>Projection(s) source</dt><dd>${esc(l.crs_observed.join(' · ')||'Non déterminée')}</dd><dt>Licence déclarée</dt><dd>${esc(l.license||'À vérifier auprès du producteur')}</dd></dl>${l.alternative_source_ids?.length>1?`<p class="micro">${l.alternative_source_ids.length} sources / formats regroupés. Les comptes ne sont pas additionnés.</p><ul>${l.alternative_source_ids.map(id=>state.catalog.layers.find(x=>x.id===id)).filter(Boolean).map(x=>'<li>'+(/^https:\/\//.test(x.url||'')?'<a href="'+esc(x.url)+'" target="_blank" rel="noopener">'+esc(x.name)+'</a>':esc(x.name))+'</li>').join('')}</ul>`:''}${l.reason?`<p class="notice">${esc(l.reason)}</p>`:''}${l.errors?.length?`<p class="notice">Conversion : ${esc(l.errors.join(' · '))}</p>`:''}<p class="micro">${l.map_count>50000?'Vue régionale agrégée par maille de 5 km ; zoomez pour afficher les objets. ':''}Affichage simplifié à 30 m. Les diagnostics utilisent les géométries reprojetées avant cette simplification, réparées si nécessaire et découpées au contour régional.</p>${l.url&&/^https:\/\//.test(l.url)?`<a class="action" href="${esc(l.url)}" target="_blank" rel="noopener">Consulter la source ↗</a>`:''}`)}
async function toggle(l,yes){if(yes===state.active.has(l.id))return;if(!yes){state.active.delete(l.id);state.loading.get(l.id)?.abort();state.loading.delete(l.id);for(const sid of state.sources.get(l.id)||[]){for(const end of ['-fill','-line','-point'])if(state.map.getLayer(sid+end))state.map.removeLayer(sid+end);if(state.map.getSource(sid))state.map.removeSource(sid)}state.sources.delete(l.id);renderLayers();saveView();return}
 state.active.add(l.id);const control=new AbortController();state.loading.set(l.id,control);state.sources.set(l.id,[]);renderLayers();saveView();let done=0;
 try{const chunks=displayChunks(l);l._viewKey=chunks.join('|');for(const chunk of chunks){const fc=chunk.startsWith('browser:')?state.customFeatures.get(l.id):await json(ROOT+chunk,control.signal);if(!state.active.has(l.id))return;const sid='atlas-'+l.id+'-'+done;state.map.addSource(sid,{type:'geojson',data:fc});state.sources.get(l.id).push(sid);const col=color(l);
 state.map.addLayer({id:sid+'-fill',source:sid,type:'fill',filter:['==',['geometry-type'],'Polygon'],paint:{'fill-color':col,'fill-opacity':.23}});
 state.map.addLayer({id:sid+'-line',source:sid,type:'line',filter:['in',['geometry-type'],['literal',['Polygon','LineString']]],paint:{'line-color':col,'line-width':['case',['==',['geometry-type'],'LineString'],2,1],'line-opacity':.85}});
 state.map.addLayer({id:sid+'-point',source:sid,type:'circle',filter:['==',['geometry-type'],'Point'],paint:{'circle-color':col,'circle-radius':5,'circle-stroke-color':'#fff','circle-stroke-width':1.3}});
 done++;$('activity').textContent='Chargement : '+done+'/'+chunks.length+' · '+l.name.slice(0,36)}
 }catch(e){if(e.name!=='AbortError'){toast(e.message);await toggle(l,false)}}finally{if(state.loading.get(l.id)===control)state.loading.delete(l.id);if(!state.loading.size){const aggregated=[...state.active].some(id=>{const l=state.catalog.layers.find(x=>x.id===id);return l?.overview_file&&state.map.getZoom()<13});$('activity').textContent=(aggregated?'Vue agrégée par mailles de 5 km · ':'Données locales · ')+fmt(state.active.size)+' couches affichées';}renderLayers()}}
function featureDetail(feature){const p=feature.properties,l=state.catalog.layers.find(l=>l.id===p._layer);if(!l)return;const attrs=Object.entries(p).filter(([k])=>!k.startsWith('_'));detail(`<div class="eyebrow">OBJET OBSERVÉ · ${esc(l.origin)}</div><h2>${esc(l.display_name||l.name)}</h2><span class="badge ${l.status==='PARTIAL'?'partial':''}">${esc(statusName(l.status))}</span><p>${esc(l.categories.join(' · '))}</p><dl><dt>Identifiant source</dt><dd>${esc(p._source_id)}</dd>${attrs.map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(typeof v==='object'?JSON.stringify(v):String(v??'—'))}</dd>`).join('')}<dt>Références</dt><dd>${esc(l.entry_ids.join(', '))}</dd>${p._neo4j_id?`<dt>Identifiant dans le graphe Neo4j</dt><dd>${esc(p._neo4j_id)}</dd>`:''}</dl><p class="notice">Une présence cartographique est une observation de la source ; elle ne suffit pas à établir une interdiction, un impact ou une priorité de restauration.</p><button class="action" id="show-source">Voir la provenance</button>`);$('show-source').onclick=()=>sourceDetail(l)}
async function analyseAt(lng,lat){try{if(!state.zones)state.zones=await json(ROOT+'zones.geojson');const zone=state.zones.features.find(f=>pointInGeometry([lng,lat],f.geometry));if(!zone){toast('Aucune maille dans le contour de Normandie à cet endroit.');return}state.selectedZone=zone;const results=await json(ROOT+'zones/'+zone.properties.id+'.json');state.map.getSource('analysis-zone').setData({type:'FeatureCollection',features:[zone]});const cat=new Set(results.layers.flatMap(r=>state.catalog.layers.find(l=>l.id===r.id)?.categories||[]));detail(`<div class="eyebrow">CONTEXTE TERRITORIAL · ${esc(zone.properties.id)}</div><h2>Que sait-on de cette zone ?</h2><p>Maille de 5 × 5 km, limitée au contour normand · ${fmt(zone.properties.area_ha)} ha.</p><div class="stats"><div><b>${fmt(results.layers.length)}</b><small>couches intersectées</small></div><div><b>${fmt(cat.size)}</b><small>thèmes représentés</small></div></div><p class="notice">Les intersections sont calculées sur les géométries de travail en Lambert-93. Les sources peuvent être partielles ou se recouvrir. Une absence de résultat ne prouve pas une absence d’enjeu.</p><p class="micro">Cliquez sur une couche pour lire sa provenance. Ce diagnostic ne calcule pas de score de renaturation.</p>${results.layers.sort((a,b)=>b.count-a.count).map(r=>{const l=state.catalog.layers.find(l=>l.id===r.id);return `<button class="result-row" data-context-layer="${r.id}"><b>${fmt(r.count)}</b>${esc(l?.name||r.id)}<br><span class="badge ${l?.status==='PARTIAL'?'partial':''}">${esc(statusName(l?.status||''))}</span></button>`}).join('')||'<p>Aucun objet intersecté dans les couches traitées.</p>'}<button id="export-zone" class="action">Exporter ce diagnostic · GeoJSON</button>`);document.querySelectorAll('[data-context-layer]').forEach(b=>b.onclick=()=>sourceDetail(state.catalog.layers.find(l=>l.id===b.dataset.contextLayer)));$('export-zone').onclick=()=>{const fc={type:'FeatureCollection',features:[{...zone,properties:{...zone.properties,analysis:results,layers:results.layers.map(r=>state.catalog.layers.find(l=>l.id===r.id)).map(l=>({id:l.id,name:l.name,status:l.status,entry_ids:l.entry_ids,url:l.url})),note:'Intersections observées, sans score automatique ni preuve d’absence.'}}]};const u=URL.createObjectURL(new Blob([JSON.stringify(fc,null,2)],{type:'application/geo+json'}));const a=document.createElement('a');a.href=u;a.download='Renatura_'+zone.properties.id+'.geojson';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};
 }catch(e){toast('Analyse indisponible : '+e.message)}}
function sourcesDialog(){const s=state.catalog.statistics;$('method').innerHTML=`<p><b>${fmt(s.mapped_features)} enregistrements géographiques préparés</b> dans ${fmt(s.mapped_layers)} sources cartographiables. Le catalogue public les organise en ${fmt(state.tree.statistics.logical_layers)} couches logiques ; les formats alternatifs et sources techniques restent dans le registre. Le catalogue conserve ${fmt(s.api_sources)} extractions API et les références des ${fmt(s.original_files)} fichiers d’origine.</p><p>Les données sont lues depuis les fichiers et pages API réellement reçus, reprojetées en Lambert-93, réparées si nécessaire, puis découpées au contour régional Etalab (généralisation 5 m). Les couches d’affichage sont simplifiées à 30 m et converties en longitude–latitude.</p><p>Les catégories sont héritées du catalogue éditorial. Les diagnostics par maille de 5 km mesurent la présence d’objets par couche avant simplification d’affichage. Ils ne constituent ni une autorisation réglementaire, ni une estimation causale, ni un score écologique validé.</p><p>Les jeux nationaux sont filtrés sur la Normandie. Les sources hors région, non spatiales, en erreur ou à projection indéterminée restent référencées. Les variantes peuvent se recouvrir et leurs comptes ne s’additionnent pas en objets uniques.</p><p><a href="guide-atlas.md" target="_blank">Guide d’utilisation et de reconstruction</a> · <a href="data/atlas/conversion-report.json" target="_blank">Rapport de conversion</a> · <a href="data/atlas/verification.json" target="_blank">Contrôles de livraison</a> · <a href="data/atlas/original-files-verification.json" target="_blank">Empreintes des originaux</a> · <a href="data/atlas/boundary_provenance.json" target="_blank">Provenance du contour régional</a> · <a href="data/atlas/catalog-v2.json" target="_blank">Catalogue structuré JSON</a> · <a href="data/atlas/catalog-v2.csv" target="_blank">CSV</a> · <a href="data/atlas/catalog-review.json" target="_blank">Doublons et sources masquées</a> · <a href="data/atlas/catalog.json" target="_blank">Registre brut des sources</a> · <a href="data/atlas/inventory.json" target="_blank">Les ${fmt(s.inventory_entries)} références catégorisées</a></p>`;
 $('source-table').innerHTML=`<h3>Les 41 fichiers d’origine</h3><table><thead><tr><th>Fichier</th><th>Disponibilité à la conversion</th></tr></thead><tbody>${state.catalog.files.map(f=>`<tr><td>${esc(f.filename)}</td><td>${f.available?'Présent':'Référencé, non présent'}</td></tr>`).join('')}</tbody></table>`;$('source-dialog').showModal()}
async function main(){try{state.catalog=await json(ROOT+'catalog.json');state.tree=await json(ROOT+'catalog-v2.json');attachImports(state,await listImports());for(const t of state.tree.themes)for(const g of t.groups)for(const l of g.layers)for(const v of l.variants)for(const id of v.source_ids){const m=state.catalog.layers.find(x=>x.id===id);if(m)m.display_name=l.display_name}const s=state.catalog.statistics;$('stats').innerHTML=`<div><b>${fmt(state.tree.statistics.logical_layers)}</b><small>couches thématiques</small></div><div><b>${fmt(s.mapped_features)}</b><small>enregistrements sources</small></div>`;for(const c of state.tree.themes){const o=document.createElement('option');o.value=c.id;o.textContent=c.display_name;$('category').append(o)}renderLayers();
 for(const id of ['search','category','origin','status','active-only'])$(id).addEventListener('input',renderLayers);$('sources').onclick=sourcesDialog;$('close-dialog').onclick=()=>$('source-dialog').close();$('mobile-filters').onclick=()=>$('sidebar').classList.toggle('open');$('clear').onclick=()=>{for(const id of [...state.active])toggle(state.catalog.layers.find(l=>l.id===id),false)};
 if(!window.L?.map)throw Error('Le moteur cartographique n’a pas pu être chargé.');state.map=new maplibregl.Map({container:'map',style:{version:8,sources:{},layers:[{id:'background',type:'background',paint:{'background-color':'#e8ede4'}}]},center:[.15,49.1],zoom:7,minZoom:5,maxZoom:18,renderWorldCopies:false,attributionControl:true});state.map.addControl(new maplibregl.NavigationControl(),'top-right');state.map.addControl(new maplibregl.ScaleControl({unit:'metric'}),'bottom-right');await new Promise(resolve=>state.map.once('load',resolve));
 state.map.addSource('osm',{type:'raster',tiles:['https://tile.openstreetmap.org/{z}/{x}/{y}.png'],tileSize:256,attribution:'© OpenStreetMap contributors',maxzoom:19});state.map.addLayer({id:'osm',type:'raster',source:'osm',paint:{'raster-opacity':.66}});$('basemap').onchange=()=>state.map.setLayoutProperty('osm','visibility',$('basemap').checked?'visible':'none');
 state.map.addSource('normandie',{type:'geojson',data:ROOT+'normandie.geojson',attribution:'Contour : Etalab / IGN · Licence Ouverte 2.0 · Sources thématiques : producteurs indiqués dans les fiches'});state.map.addLayer({id:'region-fill',type:'fill',source:'normandie',paint:{'fill-color':'#4e8759','fill-opacity':.035}});state.map.addLayer({id:'region-line',type:'line',source:'normandie',paint:{'line-color':'#355b3d','line-width':2,'line-dasharray':[3,2]}});
 state.map.addSource('analysis-zone',{type:'geojson',data:{type:'FeatureCollection',features:[]}});state.map.addLayer({id:'analysis-zone-fill',type:'fill',source:'analysis-zone',paint:{'fill-color':'#c18c39','fill-opacity':.12}});state.map.addLayer({id:'analysis-zone-line',type:'line',source:'analysis-zone',paint:{'line-color':'#a66e25','line-width':3}});
 attachOrientation(state.map.map,'leaflet');
 const bounds=[[-1.96,48.14],[1.81,50.09]];$('home').onclick=()=>state.map.fitBounds(bounds,{padding:35});const params=new URLSearchParams(location.search),view=params.get('view')?.split(',').map(Number);if(view?.length===3&&view.every(Number.isFinite))state.map.jumpTo({center:view.slice(0,2),zoom:Math.max(5,Math.min(18,view[2]))});else state.map.fitBounds(bounds,{padding:35,duration:0});state.map.on('moveend',()=>{saveView();const b=state.map.getBounds();for(const id of [...state.active]){const l=state.catalog.layers.find(l=>l.id===id);if(!l.chunk_bounds)continue;const key=displayChunks(l).join('|');if(key!==l._viewKey){toggle(l,false);toggle(l,true)}}});
 try{const health=await json('api/health');$('custom-zone').disabled=!health.spatial_database_available}catch{}
 $('custom-zone').onclick=()=>$('zone-file').click();
 $('zone-file').onchange=async()=>{try{const file=$('zone-file').files[0];if(!file)return;const data=JSON.parse(await file.text());const geometry=data.type==='Feature'?data.geometry:data.type==='FeatureCollection'&&data.features.length===1?data.features[0].geometry:data;const response=await fetch('api/analyse',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({geometry})});const result=await response.json();if(!response.ok)throw Error(result.detail||'Analyse refusée');state.map.getSource('analysis-zone').setData({type:'FeatureCollection',features:[{type:'Feature',geometry,properties:{}}]});detail(`<div class="eyebrow">ZONE PERSONNALISÉE</div><h2>${esc(file.name)}</h2><p>${esc(result.method)}</p><p class="notice">${esc(result.note)}</p>${result.layers.map(r=>`<button class="result-row" data-context-layer="${esc(r.id)}"><b>${fmt(r.count)}</b>${esc(r.name)}<br>${esc(statusName(r.collection_status))}</button>`).join('')||'<p>Aucune intersection dans les couches traitées.</p>'}`);document.querySelectorAll('[data-context-layer]').forEach(b=>b.onclick=()=>sourceDetail(state.catalog.layers.find(l=>l.id===b.dataset.contextLayer)))}catch(e){toast(e.message)}};
 $('analyse').onclick=()=>{state.analysis=!state.analysis;$('analyse').classList.toggle('active',state.analysis);$('analysis-hint').hidden=!state.analysis;state.map.getCanvas().style.cursor=state.analysis?'crosshair':''};state.map.on('click',e=>{if(state.analysis){analyseAt(e.lngLat.lng,e.lngLat.lat);return}const ids=[...state.sources.values()].flat().flatMap(id=>[id+'-fill',id+'-line',id+'-point']).filter(id=>state.map.getLayer(id));const fs=ids.length?state.map.queryRenderedFeatures(e.point,{layers:ids}):[];if(fs.length){if(fs[0].properties._aggregation)analyseAt(e.lngLat.lng,e.lngLat.lat);else featureDetail(fs[0])}});
 let communeList=[];try{communeList=await json(ROOT+'communes.json');for(const c of communeList){const o=document.createElement('option');o.value=c.name+' ('+c.code+')';$('communes').append(o)}}catch{}let locatedCommune='';const locateCommune=e=>{const q=$('commune').value.trim().toLowerCase();const c=communeList.find(c=>(c.name+' ('+c.code+')').toLowerCase()===q||c.name.toLowerCase()===q);if(c&&locatedCommune!==c.code){locatedCommune=c.code;state.map.flyTo({center:c.center,zoom:11})}else if(!c&&e.type==='change')toast('Choisissez une commune dans la liste.')};$('commune').addEventListener('input',locateCommune);$('commune').addEventListener('change',locateCommune);$('commune').addEventListener('keydown',e=>{if(e.key==='Enter')locateCommune(e)});
 const preferred=new Set(allVariants(state.tree).map(v=>v.source_id));const canonical=new Map(allVariants(state.tree).flatMap(v=>v.source_ids.map(id=>[id,v.source_id])));const requested=hydrateSelections(state.tree,[...new Set((params.get('layers')||'').split(',').filter(id=>canonical.has(id)).map(id=>canonical.get(id)))]);const defaults=requested.length?requested:allVariants(state.tree).filter(v=>v.default_visible).map(v=>v.source_id);for(const id of defaults){const l=state.catalog.layers.find(l=>l.id===id);if(l?.map_count)toggle(l,true)}$('activity').textContent='Cliquez sur un objet ou analysez une maille.';
 }catch(e){$('map-error').textContent=e.message+' Ouvrez le projet via HTTP avec run-atlas.sh.';$('map-error').hidden=false;$('activity').textContent='Chargement interrompu';console.error(e)}}
main();
if ('serviceWorker' in navigator) navigator.serviceWorker.register('./sw.js').catch(()=>{});
